        return {
            "baseline_id": baseline["baseline_id"],
            "manifest_path": baseline.get("_manifest_path"),
            "authority_refs": deepcopy(baseline["authority_refs"]),
            "engineering_methods": [
                {
                    "method_id": item["method_id"],
                    "status": item["status"],
                }
                for item in policy["method_adoptions"]
