    "TEST_DOMAIN_REVISION_ID",
    "TEST_INVARIANT_FACT_ID",
    "TEST_MODULE_ID",
    "TEST_TERM_FACT_ID",
    "adopt_portable_ddd",
    "portable_project_baseline",
]

